-- MIA-20260813-0008 - Cruzeiro do Sul / Telefone Ativo
SET @codigo := 'MIA-20260813-0008';
SET @arquivo := 'weslwy cruzeiro.mp3';
SET @cliente_nome := 'Cruzeiro do Sul';
