-- MIA-20260811-0015 - FIERGS / Ativo - Prospecção
SET @codigo := 'MIA-20260811-0015';
SET @arquivo := 'Valeria 2Fila-1063_20260806-155620_54999717299_1786042562.727451.WAV';
SET @cliente_nome := 'FIERGS';
SET @cliente_slug := 'fiergs';
SET @campanha_nome := 'Ativo - Prospecção';
SET @formulario_nome := 'FIERGS - Formulário de Monitoria TELEFONE ATIVO - Informativa e Prospecção';
SET @persona := 'IA - FIERGS ATIVO';
