-- MIA-20260806-0008 - Yduqs / Telefone Ativo
SET @codigo := 'MIA-20260806-0008';
SET @arquivo := 'THIAGO FERNANDESyduqs.mp3';
SET @cliente_nome := 'Yduqs';
SET @cliente_slug := 'yduqs';
SET @campanha_nome := 'Telefone Ativo';
SET @formulario_nome := 'Formulário Educacional | Cruzeiro';
SET @persona := 'Yduqs IA';
