-- MIA-20260805-0013 - Vero / Pré Churn
SET @codigo := 'MIA-20260805-0013';
SET @arquivo := 'promessapix.mp3';
SET @cliente_nome := 'Vero';
SET @cliente_slug := 'vero';
SET @campanha_nome := 'Pré Churn';
SET @formulario_nome := 'Avaliação de atendimento Vero - SP - IA - Pré Churn';
