-- MIA-20260727-0010 - Vero Pré Churn / Pré Churn
SET @codigo := 'MIA-20260727-0010';
SET @arquivo := '261014473_oloswebrtcagentid141410253100105022_590805512996548353_88_1414_20260701_091455.mp3';
SET @cliente_nome := 'Vero Pré Churn';
SET @cliente_slug := 'vero-pre-churn';
SET @campanha_nome := 'Pré Churn';
SET @formulario_nome := 'Avaliação de atendimento Vero - SP - IA - Pré Churn';
