-- MIA-20260617-0005 - FIRJAN / Monitorias IA - Telefone Receptivo
SET @codigo := 'MIA-20260617-0005';
SET @arquivo := 'Flavia Fila-3000_20260609-140929_5522999712444_1781024969.224811.WAV';
