SET @analise := '{"origem": "QualiTalk", "codigo": "MIA-20260415-0001", "arquivo": "11915146413-10069-176855727806900070-20260116095720.mp3", "cliente": "Não informado", "campanha": "", "persona": "Monitor teste Rapha", "formulario": "Formulário teste Raphael", "nota": 0.0, "conceito": "", "confianca": 0.8, "status": "submitted", "etapa": "finalizada", "duracao_segundos": 30, "observacoes": "O atendimento não foi cordial, faltando expressões que demonstrassem educação e respeito ao cliente.", "criada_em": "2026-04-15 15:12:00", "finalizada_em": "2026-04-15 15:12:00", "insights": ["O atendimento não foi cordial, faltando expressões que demonstrassem educação e respeito ao cliente."], "riscos": ["Monitoria abaixo da faixa de qualidade ou zerada no QualiTalk."], "proximos_passos": ["Revisar evidencias completas no arquivo de origem quando necessario."]}';
SET @avaliado_id := @avaliado_import_id;
INSERT INTO clientes (slug,nome,ativo) VALUES (@cliente_slug,@cliente_nome,1) ON DUPLICATE KEY UPDATE ativo=1;
SET @cliente_id := (SELECT id FROM clientes WHERE slug = @cliente_slug OR nome = @cliente_nome ORDER BY id LIMIT 1);
SET @campanha_id := NULL;
INSERT INTO formularios (cliente_id,nome,categoria,status,versao) VALUES (@cliente_id,@formulario_nome,'diagnostico','ativo',1) ON DUPLICATE KEY UPDATE status='ativo', categoria='diagnostico';
SET @formulario_id := (SELECT id FROM formularios WHERE cliente_id = @cliente_id AND nome = @formulario_nome AND versao = 1 LIMIT 1);
INSERT INTO formulario_secoes (formulario_id,nome,descricao,posicao) VALUES (@formulario_id,'Resultado QualiTalk','Resumo consolidado importado da base historica do QualiTalk.',1) ON DUPLICATE KEY UPDATE nome=VALUES(nome), descricao=VALUES(descricao);
SET @secao_id := (SELECT id FROM formulario_secoes WHERE formulario_id = @formulario_id AND posicao = 1 LIMIT 1);
INSERT INTO formulario_criterios (secao_id,nome,enunciado,peso_pts,eliminatoria,posicao) VALUES (@secao_id,'Resultado consolidado da analise IA','Criterio consolidado gerado a partir da nota, conceito, confianca e observacoes exportadas do QualiTalk.',100,0,1) ON DUPLICATE KEY UPDATE nome=VALUES(nome), enunciado=VALUES(enunciado);
INSERT INTO gravacoes (nome_arquivo,storage_path,mime_type,tamanho_bytes,duracao_segundos,hash_sha256,origem,cliente_id,campanha_id,avaliado_id,enviado_por_id,status_transcricao,transcrever_automatico,created_at) VALUES (@arquivo,NULL,NULL,NULL,30,SHA2(CONCAT('qualitalk-import:',@codigo),256),'integracao',@cliente_id,@campanha_id,@avaliado_id,@avaliador_import_id,'concluida',0,@criada) ON DUPLICATE KEY UPDATE nome_arquivo=VALUES(nome_arquivo), duracao_segundos=VALUES(duracao_segundos), cliente_id=VALUES(cliente_id), campanha_id=VALUES(campanha_id), avaliado_id=VALUES(avaliado_id), status_transcricao='concluida';
SET @gravacao_id := (SELECT id FROM gravacoes WHERE hash_sha256 = SHA2(CONCAT('qualitalk-import:',@codigo),256) LIMIT 1);
INSERT INTO transcricoes (gravacao_id,provedor,modelo,idioma,texto,segmentos_json,confianca,status,created_at) VALUES (@gravacao_id,'qualitalk','importacao-qualitalk','pt-BR',@resumo,@analise,0.8000,'concluida',@criada);
INSERT INTO avaliacoes (codigo,cod_gravacao,cliente_id,campanha_id,formulario_id,avaliado_id,avaliador_id,supervisor_id,categoria,origem,ia_persona,ia_modelo,ia_confianca,ia_resumo,ia_observacoes,ia_analise_json,score,zerada,quadrante,duracao_segundos,gravacao_id,data_contato,data_avaliacao,status_feedback,total_conformes,total_nao_conformes,total_nao_aplicaveis,total_criterios,avulsa,excluida_em) VALUES (@codigo,LEFT(@arquivo,60),@cliente_id,@campanha_id,@formulario_id,@avaliado_id,@avaliador_import_id,NULL,'diagnostico','ia',@persona,'qualitalk-importacao',0.8000,@resumo,@resumo,@analise,0.00,1,'1Q',30,@gravacao_id,@criada,@criada,'pendente',0,1,0,1,0,NULL) ON DUPLICATE KEY UPDATE cod_gravacao=VALUES(cod_gravacao), cliente_id=VALUES(cliente_id), campanha_id=VALUES(campanha_id), formulario_id=VALUES(formulario_id), avaliado_id=VALUES(avaliado_id), avaliador_id=VALUES(avaliador_id), categoria='diagnostico', origem='ia', ia_persona=VALUES(ia_persona), ia_modelo=VALUES(ia_modelo), ia_confianca=VALUES(ia_confianca), ia_resumo=VALUES(ia_resumo), ia_observacoes=VALUES(ia_observacoes), ia_analise_json=VALUES(ia_analise_json), score=VALUES(score), zerada=VALUES(zerada), quadrante=VALUES(quadrante), duracao_segundos=VALUES(duracao_segundos), gravacao_id=VALUES(gravacao_id), data_contato=VALUES(data_contato), data_avaliacao=VALUES(data_avaliacao), total_conformes=VALUES(total_conformes), total_nao_conformes=VALUES(total_nao_conformes), total_nao_aplicaveis=VALUES(total_nao_aplicaveis), total_criterios=VALUES(total_criterios), excluida_em=NULL;
SET @avaliacao_id := (SELECT id FROM avaliacoes WHERE codigo = @codigo LIMIT 1);
UPDATE gravacoes SET avaliacao_id = @avaliacao_id WHERE id = @gravacao_id;

-- Conferencia. `sem_operador` deve ser 0 quando a planilha traz o avaliado.
SELECT COUNT(*) AS importadas,
       SUM(a.avaliado_id = @avaliado_import_id) AS sem_operador,
       COUNT(DISTINCT a.avaliado_id)            AS operadores_distintos
  FROM avaliacoes a
 WHERE a.ia_modelo = 'qualitalk-importacao';
